// Evaluate a table generated by build_lilith_table.py at UTC epoch milliseconds.
export function readLilithTable(buffer) {
  const data = new DataView(buffer);
  if (data.byteLength < 32 || (data.byteLength - 16) % 8 !== 0 ||
      data.getUint32(0) !== 0x4c494c31) {
    throw new RangeError('Invalid Lilith table format');
  }
  const start = data.getFloat64(4, true);
  const interval = data.getUint32(12, true);
  if (!Number.isSafeInteger(start) || interval !== 900_000) {
    throw new RangeError('Invalid Lilith table time axis');
  }
  const count = (data.byteLength - 16) / 8;
  const sample = (index, column) => data.getUint32(16 + index * 8 + column * 4, true) / 1e7;
  return function lilithAt(utcMs) {
    const position = (utcMs - start) / interval;
    if (!Number.isSafeInteger(utcMs) || position < 0 || position > count - 1) {
      throw new RangeError('UTC is outside the Lilith table');
    }
    const index = Math.floor(position);
    const next = Math.min(index + 1, count - 1);
    const point = (name, column) => {
      const a = sample(index, column);
      const delta = (sample(next, column) - a + 540) % 360 - 180;
      const longitude = (a + delta * (position - index) + 360) % 360;
      return { name, longitude };
    };
    return [point('Mean Lilith', 0), point('True Lilith', 1)];
  };
}
